import React, { useState } from "react";
import { productList } from "../data/productimage"; 
import "./ProductCard.css";

const Products = () => {
  const [selectedCategory, setSelectedCategory] = useState("All");

  // Filter logic
  const filteredProducts = selectedCategory === "All"
    ? productList
    : productList.filter((product) => product.category === selectedCategory);

  // Get unique categories
  const categories = ["All", ...new Set(productList.map(p => p.category))];

  return (
    <div>
      <h1 style={{ textAlign: "center", marginTop: "40px" }}>PRODUCTS</h1>

      {/* Category Filter */}
      <div style={{ textAlign: "center", margin: "20px" }}>
        <label style={{ marginRight: "10px", fontWeight: "bold" }}>Filter by Category:</label>
        <select
          value={selectedCategory}
          onChange={(e) => setSelectedCategory(e.target.value)}
          style={{ padding: "6px 12px", borderRadius: "6px" }}
        >
          {categories.map((cat, index) => (
            <option key={index} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      {/* Products Grid */}
      <div className="product-grid">
        {filteredProducts.map((product, index) => (
          <div key={index} className="square-card">
            <img src={product.image} alt={product.name} className="square-img" />
            <div className="square-info">
              <h4>{product.name}</h4>
              <p className="product-meta">{product.category}</p>
              <p className="product-meta">₹{product.price}</p>
              <p className="product-meta">{product.brand}</p>
            </div>
            <div className="button-row">
              <button className="square-btn delete">Delete</button>
              <button className="square-btn view">View</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Products;
